-- Add ten CAT filter products with official CAT product images.
-- Keep price fields NULL: public Off Road capture does not establish supplier-unit vs OEM-list price type.
update public.part_catalog
set application_type='BOTH',
    application_evidence='Exact Cat Parts Store Compatible Models page explicitly lists Marine Engine and non-marine machine/engine groups.',
    application_source_url='https://parts.cat.com/en/catcorp/product/' || replace(part_number,' ',''),
    updated_at=now()
where part_number in ('1R-0739','1R-0749','1R-0751','1R-1807','1R-1808','7W-2326');

update public.part_catalog
set application_type='LAND',
    application_evidence='Exact Cat Parts Store Compatible Models page lists land machine/engine classes and contains no Marine Engine application group.',
    application_source_url='https://parts.cat.com/en/catcorp/product/1R-0762',
    updated_at=now()
where part_number='1R-0762';

update public.products
set application_type='BOTH',
    application_evidence='Exact Cat Parts Store Compatible Models page explicitly lists Marine Engine and non-marine machine/engine groups.',
    application_source_url='https://parts.cat.com/en/catcorp/product/' || replace(replace(sku,'CAT-',''),' ',''),
    updated_at=now()
where sku in ('CAT-1R-0749','CAT-1R-1808');

insert into public.products
 (sku,name,brand,category,machine_model,description,image_url,price_usd,price_irr,stock,status,application_type,application_evidence,application_source_url)
values
('CAT-1G-8878','فیلتر هیدرولیک و گیربکس Cat 1G-8878','Caterpillar','فیلتر و مصرفی','IT62G/IT62H، AD22، 325B، D6R/D6T، 972G و خانواده‌های دیگر','Cat Advanced Efficiency Hydraulic/Transmission Oil Filter؛ فیلتر درایوترِین با راندمان پیشرفته. سازگاری مدل‌ها از کاتالوگ رسمی CAT ثبت شده؛ تطبیق نهایی با شماره سریال و Arrangement انجام شود. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20250731-fd4fa-e38fb?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','UNVERIFIED','Cat Parts Store lists compatible machine classes; no distinct Marine Engine group found in retrieved page. Exact serial/Arrangement check required.','https://parts.cat.com/en/catcorp/product/1G-8878'),
('CAT-1R-0716','فیلتر روغن موتور استاندارد Cat 1R-0716','Caterpillar','فیلتر و مصرفی','3516، 3196، C12/C18، 3406B/C/E، 3408B/C، C32 و خانواده‌های دیگر','Cat Standard Efficiency Engine Lube Oil Filter؛ Spin-On؛ قطر 5.346 اینچ، طول 12.177 اینچ، جریان Out-to-In. CAT گروه Marine Engine و گروه‌های غیر دریایی را فهرست می‌کند. CAT گزینه ارتقای تأییدشده 1R-1808 را نیز برای کاربردهای 1R-0716 معرفی کرده است؛ جایگزینی نهایی با سریال/Arrangement بررسی شود. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-40488-07557?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store page lists Marine Engine and non-marine groups; CAT publication lists 1R-1808 as approved upgrade option for 1R-0716.','https://parts.cat.com/in/catcorp/product/1R-0716'),
('CAT-1R-0739','فیلتر روغن موتور استاندارد Cat 1R-0739','Caterpillar','فیلتر و مصرفی','3116، 3306B، 3304، 3306 و ماشین‌آلات منتخب','Cat Standard Efficiency Engine Oil Filter؛ برای کاربردهای استاندارد/مدل‌های قدیمی‌تر. CAT گروه Marine Engine شامل 3116، 3306B، 3304 و 3306 را در فهرست سازگاری درج می‌کند. 1R-1807 در پنل CAT به‌عنوان قطعه جایگزین/مقایسه‌ای نمایش داده شده، نه جانشینی قطعی برای همه سریال‌ها. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-40102-34655?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models includes Marine Engine 3116/3306B/3304/3306 and non-marine equipment groups.','https://parts.cat.com/en/catcorp/product/1R-0739'),
('CAT-1R-0750','فیلتر ثانویه سوخت Cat 1R-0750','Caterpillar','فیلتر و مصرفی','C12، 3116، 3208، 3306B، 3304، C9 و ماشین‌آلات منتخب','Cat Advanced Efficiency Secondary Fuel Filter؛ فیلتر سوخت ثانویه با راندمان پیشرفته. CAT گروه Marine Engine و کاربردهای غیر دریایی را فهرست می‌کند. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-41064-14994?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine C12/3116/3208/3306B/3304/3306/3304B/C9 and non-marine groups.','https://parts.cat.com/en/catcorp/product/1R-0750'),
('CAT-1R-0751','فیلتر سوخت Cat 1R-0751','Caterpillar','فیلتر و مصرفی','3126B، 3126، 3116، C9، C7 و ماشین‌آلات منتخب','Cat Advanced Efficiency Fuel Filter؛ فیلتر سوخت با راندمان پیشرفته. CAT گروه Marine Engine شامل 3126B، 3126، 3116، C9 و C7 را فهرست می‌کند. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-41064-09808?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine 3126B/3126/3116/C9/C7 and non-marine groups.','https://parts.cat.com/en/catcorp/product/1R-0751'),
('CAT-1R-0762','فیلتر سوخت موتور Cat 1R-0762','Caterpillar','فیلتر و مصرفی','C13، C32، C7.1، C9، C11، C12 و ماشین‌آلات منتخب','Cat Advanced High Efficiency Engine Fuel Filter؛ فیلتر سوخت موتور با راندمان بالا. صفحه رسمی CAT فهرست مدل‌های سازگار را نشان می‌دهد اما گروه Marine Engine در نتیجه بررسی‌شده وجود نداشت. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-40565-05136?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','LAND','Exact Cat Parts Store Compatible Models lists non-marine machine/engine groups; no Marine Engine group found in retrieved page.','https://parts.cat.com/en/catcorp/product/1R-0762'),
('CAT-1R-1807','فیلتر روغن موتور Cat 1R-1807','Caterpillar','فیلتر و مصرفی','3126B، 3116، 3306B، 3304، 3306، 3304B، C7 و ماشین‌آلات منتخب','Cat Advanced Efficiency Engine Oil Filter؛ راندمان بالاتر از فیلتر استاندارد 1R-0739. CAT گروه Marine Engine و کاربردهای غیر دریایی را فهرست می‌کند. پنل مقایسه CAT رابطه ارتقا را نشان می‌دهد؛ تطبیق نهایی با سریال/Arrangement الزامی است. قیمت و موجودی تأییدنشده است.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20250731-fa803-44f81?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine 3126B/3116/3306B/3304/3306/3304B/C7 and non-marine groups.','https://parts.cat.com/en/catcorp/product/1R-1807'),
('CAT-326-1644','جداکننده آب از سوخت Cat 326-1644','Caterpillar','فیلتر و مصرفی','3406B، C13، C9، C32، 3512B، 3516E و ماشین‌آلات منتخب','Cat Advanced Efficiency Fuel Water Separator؛ جداکننده آب از سوخت با راندمان پیشرفته. CAT گروه Marine Engine شامل 3406B و گروه‌های غیر دریایی را فهرست می‌کند. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20240516-27b83-fddf5?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine 3406B and non-marine engine/machine groups.','https://parts.cat.com/en/catcorp/product/326-1644'),
('CAT-360-8960','المنت فیلتر سوخت موتور Cat 360-8960','Caterpillar','فیلتر و مصرفی','C7.1، C3.4، C4.4، C3.6، C2.8 و ماشین‌آلات منتخب','Cat Ultra High Efficiency Engine Fuel Filter Element؛ المنت کارتریجی فیلتر سوخت با راندمان فوق‌بالا. CAT گروه Marine Engine C7.1 و گروه‌های غیر دریایی را فهرست می‌کند. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20180403-40211-08659?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine C7.1 and non-marine engine/machine groups.','https://parts.cat.com/en/catcorp/product/360-8960'),
('CAT-7W-2326','فیلتر روغن موتور Cat 7W-2326','Caterpillar','فیلتر و مصرفی','C4.4، 3054 و ماشین‌آلات منتخب','Cat Standard Efficiency Engine Oil Filter؛ فیلتر روغن استاندارد برای فیلتراسیون وظیفه عادی. CAT گروه Marine Engine شامل C4.4 و 3054 و گروه‌های غیر دریایی را فهرست می‌کند. قیمت و موجودی تأییدنشده است؛ تطبیق نهایی با سریال/Arrangement انجام شود.','https://caterpillar.scene7.com/is/image/Caterpillar/CM20260505-6dff6-807d8?fmt=WebP&hei=960&wid=960',NULL,NULL,0,'ACTIVE','BOTH','Exact Cat Parts Store Compatible Models explicitly includes Marine Engine C4.4/3054 and non-marine machine/engine groups.','https://parts.cat.com/en/catcorp/product/7W-2326')
on conflict (sku) do update set
 name=excluded.name,brand=excluded.brand,category=excluded.category,
 machine_model=excluded.machine_model,description=excluded.description,
 image_url=excluded.image_url,application_type=excluded.application_type,
 application_evidence=excluded.application_evidence,
 application_source_url=excluded.application_source_url,
 updated_at=now();
